"""Thread-safe task queue with cancellation tracking."""

import threading
from typing import Optional
from models import TaskJob


class SafeTaskQueue:
    def __init__(self):
        self._queue: list[TaskJob] = []
        self._cancelled: set[str] = set()
        self._lock = threading.Lock()

    def push(self, job: TaskJob) -> None:
        with self._lock:
            self._queue.append(job)

    def cancel(self, job_id: str) -> bool:
        with self._lock:
            if any(j.job_id == job_id for j in self._queue):
                # BUG: Registers ID in cancelled set, but does not update job.status
                # or synchronize status during pop_next() retrieval!
                self._cancelled.add(job_id)
                return True
            return False

    def pop_next(self) -> Optional[TaskJob]:
        with self._lock:
            # BUG: Pops raw job without checking if job.job_id was cancelled in _cancelled set
            if self._queue:
                return self._queue.pop(0)
            return None

repo_files.executor.py:
"""Task worker executor running queued jobs."""

from typing import Dict, List
from models import TaskJob
from task_queue import SafeTaskQueue


class TaskExecutor:
    def __init__(self, queue: SafeTaskQueue):
        self.queue = queue
        self.completed: Dict[str, TaskJob] = {}

    def drain_and_run(self) -> int:
        executed_count = 0
        while True:
            job = self.queue.pop_next()
            if not job:
                break
            # BUG: If job was cancelled while in queue, executor still executes fn()!
            if job.status == "CANCELLED":
                self.completed[job.job_id] = job
                continue
            try:
                job.result = job.fn()
                job.status = "COMPLETED"
                executed_count += 1
            except Exception as exc:
                job.error = str(exc)
                job.status = "FAILED"
            self.completed[job.job_id] = job
        return executed_count

